#!/usr/bin/env python3
import types,sys,json
from pathlib import Path
pb=types.ModuleType("pseudobulk_contract")
exec(compile(bytes.fromhex(""),"bundled-pseudobulk-contract","exec"),pb.__dict__)
bc=types.ModuleType("research_b_counts");bc.pb=pb
previous_bc=sys.modules.get("research_b_counts");sys.modules["research_b_counts"]=bc
normalization=types.ModuleType("research_b_state_expression")
try:
    exec(compile(bytes.fromhex(""),"bundled-b-state-expression","exec"),normalization.__dict__)
finally:
    if previous_bc is None:sys.modules.pop("research_b_counts",None)
    else:sys.modules["research_b_counts"]=previous_bc
previous_norm=sys.modules.get("research_b_state_expression");sys.modules["research_b_state_expression"]=normalization
component=types.ModuleType("b_state_score_inputs")
try:
    exec(compile(bytes.fromhex(""),"bundled-b-state-score-inputs","exec"),component.__dict__)
finally:
    if previous_norm is None:sys.modules.pop("research_b_state_expression",None)
    else:sys.modules["research_b_state_expression"]=previous_norm
score_component=component
previous_score=sys.modules.get("research_b_state_score_inputs");sys.modules["research_b_state_score_inputs"]=score_component
component=types.ModuleType("b_state_contrast_inputs")
try:
    exec(compile(bytes.fromhex(""),"bundled-b-state-contrast-inputs","exec"),component.__dict__)
finally:
    if previous_score is None:sys.modules.pop("research_b_state_score_inputs",None)
    else:sys.modules["research_b_state_score_inputs"]=previous_score

import os
OUTPUT_NAMES=['contrast-config.json','samples.tsv','decisions.tsv','audit.json']
def run():
    inputs=[Path(os.environ['AUTONOMICS_INPUT'+str(i)]) for i in range(14)]
    outputs=[Path(os.environ['AUTONOMICS_OUTPUT'+str(i)]) for i in range(4)]
    pb.require([p.name for p in outputs]==OUTPUT_NAMES and len({p.parent.absolute() for p in outputs})==1,
        'complete core B contrast preparation ports in one private directory required')
    parent=outputs[0].parent.absolute()
    pb.require(all(p.is_absolute() and '..' not in p.parts for p in outputs) and parent!=Path('/'),
        'private absolute output paths without traversal required')
    pb.require(not any(os.path.lexists(p) for p in outputs),'output exists; refusing overwrite')
    pb.require(not any(p.is_symlink() for p in [parent,*parent.parents]),'symlink output ancestor')
    parent.mkdir(parents=True,exist_ok=True);bundle=parent/'.b-state-contrast-inputs-complete'
    pb.require(not os.path.lexists(bundle),'complete scoring preparation bundle exists')
    raw=pb.bounded(inputs[0]);payloads=component.prepare(raw,dict(zip(component.INPUTS,inputs[1:])))
    pb.require(pb.sha_file(pb.regular(inputs[0]))==pb.identity(raw)['sha256'],'actual contrast recipe changed during preparation')
    component.publish(bundle,payloads)
    for target in outputs:os.link(bundle/target.name,target)
    print(json.dumps({'scope':component.SCOPE,'formal_authorized':False,'contrast_method_executed':False}))
if __name__=='__main__':
    try:run()
    except (ValueError,KeyError,TypeError,OSError,UnicodeError,pb.csv.Error,OverflowError) as e:
        print('BLOCKED: '+str(e),file=sys.stderr);raise SystemExit(2)
